import{_ as l,a0 as p,w as r,s as d,ao as a,I as e,x as o,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Linux 黑話解釋：什麼是定時任務 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 黑話解釋：什麼是定時任務 | LCTT (202112) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 黑話解釋：什麼是定時任務 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 黑話解釋：什麼是定時任務 | LCTT (202112) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202112/20211208 Linux Jargon Buster- What is a Cron Job in Linux","title":"Linux 黑話解釋：什麼是定時任務","tag":"202112","desc":""},"relativePath":"202112/20211208 Linux Jargon Buster- What is a Cron Job in Linux.md","filePath":"[post].md"}'),c={name:"202112/20211208 Linux Jargon Buster- What is a Cron Job in Linux.md"},u={class:"table-wrap"};function b(h,t,g,m,f,k){const s=p("Link");return r(),d("div",null,[t[26]||(t[26]=a('<h1 id="linux-黑話解釋-什麼是定時任務" tabindex="-1">Linux 黑話解釋：什麼是定時任務 <a class="header-anchor" href="#linux-黑話解釋-什麼是定時任務" aria-label="Permalink to “Linux 黑話解釋：什麼是定時任務”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202112/16/112554pna46aemuh84ta3m.jpg" alt=""></p><p>在本期的《Linux 黑話解釋》系列文章中，你將瞭解到 Linux 中的<ruby>定時任務<rt>cron job</rt></ruby>功能。你將通過學習編輯 <code>crontab</code> 文件來創建定時任務。</p><h3 id="何為定時任務" tabindex="-1">何為定時任務 <a class="header-anchor" href="#何為定時任務" aria-label="Permalink to “何為定時任務”">​</a></h3><p><code>cron</code> 是一個用於按計劃運行短小且快速的命令的實用命令列工具。該工具是一個方便、經典的系統管理工具，通過和其他工具結合使用可以自動運行各式各樣的任務。比如，有些人通過把 <code>rsync</code> 和 <code>cron</code> 結合使用，在特定的時間自動創建每日備份和每週備份。也有些人使用 <code>cron</code> 來分析服務器日誌，並且結合郵件系統功能，在日誌檢測到錯誤時自動發送告警郵件。</p><p><code>cron</code> 就如同“瑞士軍刀”一樣，可以多場景多樣化使用。儘可能發揮你的想像，去挖掘它的功能。</p><p>其實 <code>cron</code> 的使用很容易上手，只需要幾秒鐘。不過在我們開始上手之前，先來討論下幾個經常容易混淆的概念。</p><h3 id="cron、定時任務、crontab" tabindex="-1">cron、定時任務、crontab <a class="header-anchor" href="#cron、定時任務、crontab" aria-label="Permalink to “cron、定時任務、crontab”">​</a></h3><p>有三個術語比較容易混淆：<code>cron</code>、定時任務和 <code>crontab</code>，讓我們來看看它們的含義：</p>',9)),e("div",u,[e("table",null,[t[7]||(t[7]=e("thead",null,[e("tr",null,[e("th",null,"術語"),e("th",null,"含義")])],-1)),e("tbody",null,[e("tr",null,[t[3]||(t[3]=e("td",null,[e("code",null,"cron")],-1)),e("td",null,[t[1]||(t[1]=o("這是安裝在系統上的實際執行定時任務的 ",-1)),n(s,{href:"https://itsfoss.com/linux-daemons/"},{default:i(()=>[...t[0]||(t[0]=[o("守護進程",-1)])]),_:1}),t[2]||(t[2]=o("。",-1))])]),t[6]||(t[6]=e("tr",null,[e("td",null,"定時任務"),e("td",null,[o("“任務”是指一段啓動並運行的程序。"),e("code",null,"cron"),o(" 可以按照約定的時間計劃運行各種任務，這樣的任務通常叫做“定時任務”。")])],-1)),e("tr",null,[e("td",null,[n(s,{href:"https://linuxhandbook.com/crontab/"},{default:i(()=>[...t[4]||(t[4]=[o("crontab",-1)])]),_:1})]),t[5]||(t[5]=e("td",null,[o("這是一個文件，用於定義定時任務。一個 "),e("code",null,"crontab"),o(" 文件可以通過表格形式（每一行就是一個定時任務）定義多個定時任務。")],-1))])])])]),t[27]||(t[27]=a('<p>來看一個簡單例子：創建一個定時任務，每小時向 <code>crontabl_log.txt</code> 文件打印 <code>Linux is cool!</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0 * * * *  echo &quot;Linux is Cool!&quot; &gt;&gt; ~/crontab_log.txt</span></span></code></pre></div><p>是不是這麼個簡單定時任務的例子都讓你感到驚恐，這是因為你需要懂得如何去讀懂一個定時任務的屬性。</p><p>我將在後文中講述這個基礎理論知識。</p><h3 id="上手-cron" tabindex="-1">上手 cron <a class="header-anchor" href="#上手-cron" aria-label="Permalink to “上手 cron”">​</a></h3><p>我們通過另一個例子來看看 <code>cron</code> 如何工作。</p><p>為了創建定時任務（或者説 <code>cron</code> 將要執行的命令任務），你只需要運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>crontab -e</span></span></code></pre></div><p>這將會打開一個文件，用於編輯定時任務：</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/12/crontab-file.webp?resize=800%2C673&amp;ssl=1" alt="Crontab default view"></p><p>其中，所有以 <code>#</code> 開頭的行都是註釋，用於指導你如何使用 <code>cron</code>，如果覺得沒用可以刪除它們。</p><p>我們將創建如下任務，作為我們的第一個定時任務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>* * * * * touch ~/crontab_test</span></span></code></pre></div><p>讓我快速看看該任務將會做什麼：</p><p>定時任務都是以 “分鐘 小時 天 月 周 命令” 形式呈現：</p><ul><li>分鐘：指該任務在哪一分鐘會被執行。所以，該值為 <code>0</code> 則代表在每個小時開始時運行，<code>5</code> 則代表在每個小時的第 5 分鐘會運行。</li><li>小時：指該任務在一天中的哪個小時會被執行，取值範圍為 <code>0-23</code>。沒有 <code>24</code> 的原因是 <code>23</code> 時的末尾是半夜 <code>11:59</code>，然後就是每天的開始 <code>0</code> 時。分鐘的取值範圍定義邏輯與之類似。</li><li>天：指一個月中的哪一天執行該任務，取值範圍是 <code>1-31</code>（不同於前面的分鐘和小時從 <code>0</code> 開始取值）。</li><li>月：指該任務在哪個月被執行，取值範圍是 <code>1-12</code>。</li><li>周：指該任務在星期幾被執行，從週日開始算起，取值範圍是 <code>0-6</code>（分別對應週日、週一到週六）。</li><li>命令：是你想要運行的命令任務。</li></ul><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/crontab-explanation.webp?resize=800%2C450&amp;ssl=1" alt=""></p>',17)),e("p",null,[t[9]||(t[9]=o("如果想對 “分鐘 小時 天 月 周” 部分有更詳細的理解，可以參考 ",-1)),n(s,{href:"https://crontab.guru/"},{default:i(()=>[...t[8]||(t[8]=[o("Crontab guru 網站",-1)])]),_:1}),t[10]||(t[10]=o("，該網站可以幫助你理解正在執行什麼。",-1))]),t[28]||(t[28]=a(`<p>接着之前的例子 <code>* * * * * touch ~/crontab_test</code>，表示每分鐘創建一次 <code>~/crontab_test</code> 文件。</p><p>讓我們將該任務編輯進 <code>crontab</code> 然後看看執行結果：</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/12/cron-example-1.webp?resize=557%2C241&amp;ssl=1" alt=""></p><p>等到下一分鐘，你就會發現你的家目錄下多了文件 <code>crontab_test</code>:</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/12/result-of-cron-job.webp?resize=557%2C241&amp;ssl=1" alt=""></p><p>這便是 <code>cron</code> 的基礎應用示例。</p><h3 id="一個實用的定時任務示例" tabindex="-1">一個實用的定時任務示例 <a class="header-anchor" href="#一個實用的定時任務示例" aria-label="Permalink to “一個實用的定時任務示例”">​</a></h3><p>假設你想創建一個腳本，用於拷貝多個目錄內容到一個路徑並打包作為備份，該如何實現？</p><p>通過 <code>cron</code> 定時任務就可以很容易實現該功能。</p><p>請看如下腳本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/usr/bin/bash</span></span>
<span class="line"><span>echo &quot;Backing up...&quot;</span></span>
<span class="line"><span>mkdir -p ~/.local/tmp/</span></span>
<span class="line"><span>tar -Pc ~/Documents/ -f ~/.local/tmp/backup.gz</span></span></code></pre></div><p>該腳本做了如下事情：</p><ol><li>確保備份路徑目錄 <code>~/.local/tmp/</code> 存在。</li><li>將目錄 <code>~/Documents/</code> 下的所有內容打包至文件 <code>~/.local/tmp/backup.gz</code>。</li></ol><p>我們先來手動運行該腳本，看看它到底如何工作。</p><p>首先，我們在家目錄（<code>~</code>）下創建該腳本，命令為 <code>backup_script</code>，如下圖所示：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/12/complex-cron-example.webp?resize=548%2C295&amp;ssl=1" alt=""></p><p>然後編輯 <code>backup_script</code> 腳本，寫入上面那個腳本代碼。</p><p>接着，賦予 <code>backup_script</code> 可執行權限：</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/12/complex-cron-example-1.webp?resize=548%2C385&amp;ssl=1" alt=""></p><p>最後運行腳本 <code>~/backup_script</code>，進行功能驗證：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/12/complex-cron-result.png?resize=800%2C220&amp;ssl=1" alt=""></p><p>你可以通過運行命令 <code>tar -xf ~/.local/tmp/backup.gz -C &lt;output_dir&gt;</code> 來進行備份恢復，這裏 <code>&lt;output_dir&gt;</code> 是指文件要恢復到的路徑目錄。</p><p>接下來，就可以用 <code>cron</code> 工具來進行定時任務運行該腳本了。</p><p>舉個例子，假設需要每天的凌晨 3 點運行該備份腳本，你可以在 <code>crontab</code> 中輸入如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>* 3 * * * ~/backup_script</span></span></code></pre></div><p>這樣你就可以每天自動進行備份操作了。</p><h3 id="後記" tabindex="-1">後記 <a class="header-anchor" href="#後記" aria-label="Permalink to “後記”">​</a></h3><p>本文簡單介紹了定時任務功能。儘管我不確定 Linux 桌面用户使用該功能多不多，但我知道定時任務功能被許多系統管理員廣泛應用。如果你有什麼想法，歡迎在評論區留言。</p><hr>`,29)),e("p",null,[t[12]||(t[12]=o("via: ",-1)),n(s,{href:"https://itsfoss.com/cron-job/"},{default:i(()=>[...t[11]||(t[11]=[o("https://itsfoss.com/cron-job/",-1)])]),_:1})]),e("p",null,[t[17]||(t[17]=o("作者：",-1)),n(s,{href:"https://itsfoss.com/author/hunter/"},{default:i(()=>[...t[13]||(t[13]=[o("Hunter Wittenborn",-1)])]),_:1}),t[18]||(t[18]=o(" 選題：",-1)),n(s,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[14]||(t[14]=[o("lujun9972",-1)])]),_:1}),t[19]||(t[19]=o(" 譯者：",-1)),n(s,{href:"https://github.com/jrglinux"},{default:i(()=>[...t[15]||(t[15]=[o("jrglinux",-1)])]),_:1}),t[20]||(t[20]=o(" 校對：",-1)),n(s,{href:"https://github.com/wxy"},{default:i(()=>[...t[16]||(t[16]=[o("wxy",-1)])]),_:1})]),e("p",null,[t[23]||(t[23]=o("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[21]||(t[21]=[o("LCTT",-1)])]),_:1}),t[24]||(t[24]=o(" 原創編譯，",-1)),n(s,{href:"https://linux.cn/"},{default:i(()=>[...t[22]||(t[22]=[o("Linux中國",-1)])]),_:1}),t[25]||(t[25]=o(" 榮譽推出",-1))])])}const L=l(c,[["render",b]]);export{T as __pageData,L as default};
